  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "CK isoform composition"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "CK isoform composition"? (Select all that apply)', '[{"id": "a", "text": "CK-BB is minimal in routine blood profile here."}, {"id": "b", "text": "CK-BB is dominant in healthy blood in this note."}, {"id": "c", "text": "CK-MB normal proportion is small."}, {"id": "d", "text": "CK-MM is dominant fraction in this note."}, {"id": "e", "text": "CK-MB comprises most CK in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: CK-MM is 96–100%, CK-MB is 0–5%, and CK-BB is about 0% in normal distribution listed.', 'Cardiac Biomarkers - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CK-MB timeline/use" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "CK-MB timeline/use" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-MB remains elevated for 14 days in this note."}, {"id": "b", "text": "Rise/peak/normalization windows are listed."}, {"id": "c", "text": "CK-MB normalizes faster than troponin."}, {"id": "d", "text": "CK-MB has no role in reinfarction in this note."}, {"id": "e", "text": "CK-MB is useful for reinfarction detection."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-MB rises 4–6h, peaks 18–24h, normalizes 48–72h, and is useful for MI and re-infarction detection.', 'Cardiac Biomarkers - NCLEX', true, 58, 1, true);
