  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CK-MM limitation" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "CK-MM limitation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-MM excludes muscle injury in this note."}, {"id": "b", "text": "CK-MM source is skeletal muscle."}, {"id": "c", "text": "CK-MM is not cardiac-specific in this note."}, {"id": "d", "text": "CK-MM is most cardiac-specific marker in this note."}, {"id": "e", "text": "CK-MM can rise in rhabdomyolysis."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-MM reflects skeletal muscle injury such as rhabdomyolysis and is not cardiac-specific.', 'Cardiac Biomarkers - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-BB comes from ventricular myocardium in this note."}, {"id": "b", "text": "CK-BB can relate to bowel infarction in note."}, {"id": "c", "text": "CK-BB is linked to brain/smooth muscle."}, {"id": "d", "text": "CK-BB is not cardiac marker of choice."}, {"id": "e", "text": "CK-BB is preferred biomarker for MI in this note."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: CK-BB is associated with brain/smooth muscle injury and is not used for cardiac monitoring.', 'Cardiac Biomarkers - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "BNP physiology" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "BNP physiology" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Volume overload increases BNP."}, {"id": "b", "text": "BNP reflects wall stress in this note."}, {"id": "c", "text": "BNP is unrelated to ventricular stretch in this note."}, {"id": "d", "text": "Ventricular stretch triggers BNP release."}, {"id": "e", "text": "BNP rises only from skeletal injury in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: BNP is released from ventricular myocytes when stretched by volume overload.', 'Cardiac Biomarkers - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "BNP ranges"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "BNP ranges"? (Select all that apply)', '[{"id": "a", "text": "100–400 suggests possible HF."}, {"id": "b", "text": "BNP <20 defines severe HF in this note."}, {"id": "c", "text": ">400 suggests likely HF exacerbation."}, {"id": "d", "text": "BNP >400 excludes HF in this note."}, {"id": "e", "text": "BNP <100 is normal in this note."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP normal is <100 pg/mL; 100–400 possible HF; >400 likely HF exacerbation.', 'Cardiac Biomarkers - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "BNP clinical use" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "BNP clinical use" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BNP has no prognostic value in this note."}, {"id": "b", "text": "BNP can separate cardiac vs pulmonary dyspnea causes."}, {"id": "c", "text": "BNP confirms MI infarct size directly in this note."}, {"id": "d", "text": "BNP helps guide diuretic and discharge decisions."}, {"id": "e", "text": "Higher BNP correlates with worse prognosis."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP helps differentiate cardiac from pulmonary dyspnea, guides diuresis/discharge, and higher BNP suggests worse prognosis.', 'Cardiac Biomarkers - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "BNP not MI marker" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "BNP not MI marker" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Troponin remains MI marker priority."}, {"id": "b", "text": "BNP indicates volume overload, not infarction specificity."}, {"id": "c", "text": "BNP is the most specific MI marker in this note."}, {"id": "d", "text": "BNP rise alone proves STEMI in this note."}, {"id": "e", "text": "BNP is HF-oriented biomarker in note."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: The note explicitly states BNP does not indicate MI; it indicates fluid overload/heart failure context.', 'Cardiac Biomarkers - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
