  VALUES (v_test_id, v_topic_id, 'Which statements about "Myoglobin kinetics" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Myoglobin kinetics" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Rise occurs 1–3 hours."}, {"id": "b", "text": "Myoglobin rises after troponin peak in this note."}, {"id": "c", "text": "Myoglobin is earliest riser in note."}, {"id": "d", "text": "Normalization occurs by about 24 hours."}, {"id": "e", "text": "Myoglobin stays elevated 10 days in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin rises first at 1–3h after MI but normalizes quickly within 24h.', 'Cardiac Biomarkers - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "Myoglobin limitation/use"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "Myoglobin limitation/use"? (Select all that apply)', '[{"id": "a", "text": "Myoglobin comes from skeletal and cardiac muscle."}, {"id": "b", "text": "Normal early myoglobin lowers immediate MI likelihood."}, {"id": "c", "text": "Myoglobin alone confirms MI in this note."}, {"id": "d", "text": "Myoglobin is highly cardiac-specific in this note."}, {"id": "e", "text": "Specificity is limited in this note."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin is not cardiac-specific and is used mainly for early rule-out when normal at around 3h.', 'Cardiac Biomarkers - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Timeline comparison" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Timeline comparison" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Myoglobin persists longest in this note."}, {"id": "b", "text": "CK-MB clears before troponin."}, {"id": "c", "text": "Myoglobin rises earliest in this note."}, {"id": "d", "text": "Troponin clears before CK-MB in this note."}, {"id": "e", "text": "Troponin persists the longest."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Timeline summary: myoglobin earliest/shortest, CK-MB intermediate, troponin longest duration.', 'Cardiac Biomarkers - NCLEX', true, 68, 1, true);
