  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "BUN/creatinine interpretation" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "BUN/creatinine interpretation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "High BUN + high creatinine suggests renal impairment."}, {"id": "b", "text": "High BUN with normal creatinine proves MI in this note."}, {"id": "c", "text": "Creatinine normal 0.6–1.2 is listed."}, {"id": "d", "text": "Normal creatinine excludes dehydration in this note."}, {"id": "e", "text": "BUN normal range 7–20 is listed."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: BUN 7–20 and creatinine 0.6–1.2 are listed normal; high BUN with normal creatinine suggests dehydration, while both high suggest renal impairment.', 'Cardiac Biomarkers - NCLEX', true, 69, 1, true);
