  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BUN/Cr are unrelated to hemodynamics in this note."}, {"id": "b", "text": "Low cardiac output can impair renal perfusion."}, {"id": "c", "text": "Renal markers may rise in low-output states."}, {"id": "d", "text": "Cardiorenal relationship is explicitly noted."}, {"id": "e", "text": "Renal perfusion is unaffected by cardiac output in this note."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Reduced cardiac output can increase BUN/creatinine due to renal hypoperfusion.', 'Cardiac Biomarkers - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Lactate and ABG significance" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Lactate and ABG significance" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "ABG is irrelevant in shock in this note."}, {"id": "b", "text": "Metabolic acidosis can occur in shock/MI."}, {"id": "c", "text": "ABG/lactate assist shock severity assessment."}, {"id": "d", "text": "Lactate >2 indicates hypoperfusion in note."}, {"id": "e", "text": "Lactate <0.2 is the shock threshold in this note."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Shock/MI may show metabolic acidosis; lactate >2 mmol/L indicates tissue hypoperfusion and helps gauge shock severity.', 'Cardiac Biomarkers - NCLEX', true, 71, 1, true);
