  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "NCLEX synthesis" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "NCLEX synthesis" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Myoglobin is best reinfarction marker in this note."}, {"id": "b", "text": "BNP replaces troponin for MI confirmation in this note."}, {"id": "c", "text": "CK-MB favored for reinfarction detection."}, {"id": "d", "text": "Troponin is top MI marker in NCLEX summary."}, {"id": "e", "text": "BNP and myoglobin have distinct non-overlapping roles."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX summary: Troponin is gold standard and longest-lasting, CK-MB best for reinfarction, BNP for HF dyspnea differentiation, myoglobin earliest but nonspecific.', 'Cardiac Biomarkers - NCLEX', true, 73, 1, true);
