  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Biomarker purpose" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Biomarker purpose" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "They assist MI and HF evaluation."}, {"id": "b", "text": "Biomarkers only diagnose pulmonary embolism in this note."}, {"id": "c", "text": "They assess cardiac stress patterns."}, {"id": "d", "text": "Biomarkers rise when cardiac cells are damaged."}, {"id": "e", "text": "Cardiac injury does not alter biomarker levels in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment.', 'Cardiac Biomarkers - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
