  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Troponin T kinetics" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Troponin T kinetics" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Rise/peak times mirror early troponin kinetics."}, {"id": "b", "text": "Troponin T normal is <0.01 ng/mL."}, {"id": "c", "text": "Troponin T is gone by 24 hours in this note."}, {"id": "d", "text": "Duration extends up to 10–14 days."}, {"id": "e", "text": "Troponin T has no normal reference in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Troponin T normal is <0.01 ng/mL, rises 3–6h, peaks 12–24h, and normalizes over 10–14 days.', 'Cardiac Biomarkers - NCLEX', true, 78, 1, true);
