  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "hsTnT utility" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "hsTnT utility" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Useful in early subtle MI detection."}, {"id": "b", "text": "hsTnT is used only for heart failure in this note."}, {"id": "c", "text": "hsTnT detects smaller infarcts in this note."}, {"id": "d", "text": "hsTnT is less sensitive than CK-MB in this note."}, {"id": "e", "text": "Sensitivity is higher than conventional threshold-only approach."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: High-sensitivity Troponin T can detect smaller myocardial infarctions.', 'Cardiac Biomarkers - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "CK isoform composition" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "CK isoform composition" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-BB is minimal in routine blood profile here."}, {"id": "b", "text": "CK-MM is dominant fraction in this note."}, {"id": "c", "text": "CK-MB normal proportion is small."}, {"id": "d", "text": "CK-MB comprises most CK in this note."}, {"id": "e", "text": "CK-BB is dominant in healthy blood in this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: CK-MM is 96–100%, CK-MB is 0–5%, and CK-BB is about 0% in normal distribution listed.', 'Cardiac Biomarkers - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "CK-MB timeline/use" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "CK-MB timeline/use" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "CK-MB is useful for reinfarction detection."}, {"id": "b", "text": "CK-MB normalizes faster than troponin."}, {"id": "c", "text": "Rise/peak/normalization windows are listed."}, {"id": "d", "text": "CK-MB has no role in reinfarction in this note."}, {"id": "e", "text": "CK-MB remains elevated for 14 days in this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: CK-MB rises 4–6h, peaks 18–24h, normalizes 48–72h, and is useful for MI and re-infarction detection.', 'Cardiac Biomarkers - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "CK-MM limitation"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "CK-MM limitation"? (Select all that apply)', '[{"id": "a", "text": "CK-MM can rise in rhabdomyolysis."}, {"id": "b", "text": "CK-MM is most cardiac-specific marker in this note."}, {"id": "c", "text": "CK-MM is not cardiac-specific in this note."}, {"id": "d", "text": "CK-MM excludes muscle injury in this note."}, {"id": "e", "text": "CK-MM source is skeletal muscle."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-MM reflects skeletal muscle injury such as rhabdomyolysis and is not cardiac-specific.', 'Cardiac Biomarkers - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "CK-BB limitation" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "CK-BB is linked to brain/smooth muscle."}, {"id": "b", "text": "CK-BB is preferred biomarker for MI in this note."}, {"id": "c", "text": "CK-BB can relate to bowel infarction in note."}, {"id": "d", "text": "CK-BB comes from ventricular myocardium in this note."}, {"id": "e", "text": "CK-BB is not cardiac marker of choice."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CK-BB is associated with brain/smooth muscle injury and is not used for cardiac monitoring.', 'Cardiac Biomarkers - NCLEX', true, 83, 1, true);
