  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "BNP physiology" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "BNP physiology" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Ventricular stretch triggers BNP release."}, {"id": "b", "text": "Volume overload increases BNP."}, {"id": "c", "text": "BNP rises only from skeletal injury in this note."}, {"id": "d", "text": "BNP reflects wall stress in this note."}, {"id": "e", "text": "BNP is unrelated to ventricular stretch in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: BNP is released from ventricular myocytes when stretched by volume overload.', 'Cardiac Biomarkers - NCLEX', true, 84, 1, true);
