  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "BNP ranges" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "BNP ranges" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "BNP <20 defines severe HF in this note."}, {"id": "b", "text": "BNP >400 excludes HF in this note."}, {"id": "c", "text": "100–400 suggests possible HF."}, {"id": "d", "text": "BNP <100 is normal in this note."}, {"id": "e", "text": ">400 suggests likely HF exacerbation."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP normal is <100 pg/mL; 100–400 possible HF; >400 likely HF exacerbation.', 'Cardiac Biomarkers - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "BNP clinical use" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "BNP clinical use" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Higher BNP correlates with worse prognosis."}, {"id": "b", "text": "BNP can separate cardiac vs pulmonary dyspnea causes."}, {"id": "c", "text": "BNP has no prognostic value in this note."}, {"id": "d", "text": "BNP confirms MI infarct size directly in this note."}, {"id": "e", "text": "BNP helps guide diuretic and discharge decisions."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: BNP helps differentiate cardiac from pulmonary dyspnea, guides diuresis/discharge, and higher BNP suggests worse prognosis.', 'Cardiac Biomarkers - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "BNP not MI marker"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "BNP not MI marker"? (Select all that apply)', '[{"id": "a", "text": "BNP indicates volume overload, not infarction specificity."}, {"id": "b", "text": "BNP is the most specific MI marker in this note."}, {"id": "c", "text": "BNP rise alone proves STEMI in this note."}, {"id": "d", "text": "BNP is HF-oriented biomarker in note."}, {"id": "e", "text": "Troponin remains MI marker priority."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: The note explicitly states BNP does not indicate MI; it indicates fluid overload/heart failure context.', 'Cardiac Biomarkers - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
