  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Myoglobin kinetics" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Myoglobin kinetics" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Myoglobin stays elevated 10 days in this note."}, {"id": "b", "text": "Normalization occurs by about 24 hours."}, {"id": "c", "text": "Myoglobin rises after troponin peak in this note."}, {"id": "d", "text": "Myoglobin is earliest riser in note."}, {"id": "e", "text": "Rise occurs 1–3 hours."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin rises first at 1–3h after MI but normalizes quickly within 24h.', 'Cardiac Biomarkers - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Myoglobin limitation/use" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Myoglobin limitation/use" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Myoglobin comes from skeletal and cardiac muscle."}, {"id": "b", "text": "Normal early myoglobin lowers immediate MI likelihood."}, {"id": "c", "text": "Myoglobin alone confirms MI in this note."}, {"id": "d", "text": "Specificity is limited in this note."}, {"id": "e", "text": "Myoglobin is highly cardiac-specific in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Myoglobin is not cardiac-specific and is used mainly for early rule-out when normal at around 3h.', 'Cardiac Biomarkers - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Timeline comparison" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "Timeline comparison" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "Troponin persists the longest."}, {"id": "b", "text": "CK-MB clears before troponin."}, {"id": "c", "text": "Troponin clears before CK-MB in this note."}, {"id": "d", "text": "Myoglobin rises earliest in this note."}, {"id": "e", "text": "Myoglobin persists longest in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Timeline summary: myoglobin earliest/shortest, CK-MB intermediate, troponin longest duration.', 'Cardiac Biomarkers - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "BUN/creatinine interpretation"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "BUN/creatinine interpretation"? (Select all that apply)', '[{"id": "a", "text": "Normal creatinine excludes dehydration in this note."}, {"id": "b", "text": "BUN normal range 7–20 is listed."}, {"id": "c", "text": "High BUN with normal creatinine proves MI in this note."}, {"id": "d", "text": "Creatinine normal 0.6–1.2 is listed."}, {"id": "e", "text": "High BUN + high creatinine suggests renal impairment."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: BUN 7–20 and creatinine 0.6–1.2 are listed normal; high BUN with normal creatinine suggests dehydration, while both high suggest renal impairment.', 'Cardiac Biomarkers - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Low-output renal effect" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Cardiorenal relationship is explicitly noted."}, {"id": "b", "text": "Renal markers may rise in low-output states."}, {"id": "c", "text": "BUN/Cr are unrelated to hemodynamics in this note."}, {"id": "d", "text": "Renal perfusion is unaffected by cardiac output in this note."}, {"id": "e", "text": "Low cardiac output can impair renal perfusion."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Reduced cardiac output can increase BUN/creatinine due to renal hypoperfusion.', 'Cardiac Biomarkers - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Lactate and ABG significance" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Lactate and ABG significance" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Lactate <0.2 is the shock threshold in this note."}, {"id": "b", "text": "Metabolic acidosis can occur in shock/MI."}, {"id": "c", "text": "ABG/lactate assist shock severity assessment."}, {"id": "d", "text": "Lactate >2 indicates hypoperfusion in note."}, {"id": "e", "text": "ABG is irrelevant in shock in this note."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Shock/MI may show metabolic acidosis; lactate >2 mmol/L indicates tissue hypoperfusion and helps gauge shock severity.', 'Cardiac Biomarkers - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Lipid panel targets" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Lipid panel targets" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Total cholesterol target <200 is listed."}, {"id": "b", "text": "LDL >160 is optimal in high-risk in this note."}, {"id": "c", "text": "HDL under 20 is protective in this note."}, {"id": "d", "text": "HDL >60 is protective per note."}, {"id": "e", "text": "LDL <70 is listed for high-risk."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Desired lipids listed are total cholesterol <200, LDL <70 in high-risk patients, and HDL >60 as protective.', 'Cardiac Biomarkers - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NCLEX synthesis" in Cardiac Biomarkers are correct? (Select all that apply)', 'Which statements about "NCLEX synthesis" in Cardiac Biomarkers are correct? (Select all that apply)', '[{"id": "a", "text": "BNP and myoglobin have distinct non-overlapping roles."}, {"id": "b", "text": "Myoglobin is best reinfarction marker in this note."}, {"id": "c", "text": "Troponin is top MI marker in NCLEX summary."}, {"id": "d", "text": "CK-MB favored for reinfarction detection."}, {"id": "e", "text": "BNP replaces troponin for MI confirmation in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: NCLEX summary: Troponin is gold standard and longest-lasting, CK-MB best for reinfarction, BNP for HF dyspnea differentiation, myoglobin earliest but nonspecific.', 'Cardiac Biomarkers - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Biomarkers, which findings or actions relate to "Biomarker purpose"? (Select all that apply)', 'For Cardiac Biomarkers, which findings or actions relate to "Biomarker purpose"? (Select all that apply)', '[{"id": "a", "text": "Biomarkers rise when cardiac cells are damaged."}, {"id": "b", "text": "They assess cardiac stress patterns."}, {"id": "c", "text": "They assist MI and HF evaluation."}, {"id": "d", "text": "Cardiac injury does not alter biomarker levels in this note."}, {"id": "e", "text": "Biomarkers only diagnose pulmonary embolism in this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Cardiac biomarkers are blood proteins released after cardiac cell injury and are used for MI/HF diagnosis and stress assessment.', 'Cardiac Biomarkers - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Serial testing principle" in Cardiac Biomarkers? (Select all that apply)', 'The nurse is planning care. Which items apply to "Serial testing principle" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "One elevated value always confirms MI in this note."}, {"id": "b", "text": "Single value alone is insufficient for MI confirmation."}, {"id": "c", "text": "Rise-and-fall pattern supports MI."}, {"id": "d", "text": "Serial testing is unnecessary in acute chest pain in this note."}, {"id": "e", "text": "Serial q3–6h testing is listed."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Serial values every 3–6 hours are needed, and a rise-and-fall pattern supports MI rather than one isolated elevation.', 'Cardiac Biomarkers - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Troponin priority" in Cardiac Biomarkers? (Select all that apply)', 'Which of the following are consistent with "Troponin priority" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Troponin has highest NCLEX priority in this section."}, {"id": "b", "text": "Troponin is both highly sensitive and specific in note."}, {"id": "c", "text": "Myoglobin is more specific than troponin in this note."}, {"id": "d", "text": "Troponin is gold standard for MI in this note."}, {"id": "e", "text": "BNP is the gold standard for MI in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Troponin is the most specific and sensitive biomarker for MI and is the gold standard in this note.', 'Cardiac Biomarkers - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Troponin I kinetics" in Cardiac Biomarkers? (Select all that apply)', 'During reassessment, which observations align with "Troponin I kinetics" in Cardiac Biomarkers? (Select all that apply)', '[{"id": "a", "text": "Troponin I can stay elevated for 7–10 days."}, {"id": "b", "text": "Troponin I peak occurs at 2 hours in this note."}, {"id": "c", "text": "Troponin I rises at 3–6 hours."}, {"id": "d", "text": "Troponin I normalizes within 12 hours in this note."}, {"id": "e", "text": "Peak is 12–24 hours."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Troponin I normal is <0.04 ng/mL, rises 3–6h, peaks 12–24h, normalizes in 7–10 days.', 'Cardiac Biomarkers - NCLEX', true, 100, 1, true);
